using System.Net;using System.Text;using SalekhPos.Desktop.Infrastructure.Management;using Xunit;namespace SalekhPos.Desktop.Tests;public sealed class IntegrationManagerHttpTests{[Fact]public async Task ListsConnections(){var o=Guid.NewGuid();var id=Guid.NewGuid();using var c=Client(_=>Json($$"""{"items":[{"id":"{{id:D}}","provider":"http","displayName":"ERP","endpoint":"https://erp.test","status":"active","createdAt":"2026-09-18T08:00:00Z","updatedAt":"2026-09-18T08:00:00Z"}],"nextCursor":null}"""));var p=await new HttpIntegrationManager(c).ConnectionsAsync(o,default);Assert.Single(p.Items);}private static HttpClient Client(Func<HttpRequestMessage,HttpResponseMessage> f)=>new(new H(f)){BaseAddress=new("https://pos.test/")};private static HttpResponseMessage Json(string x)=>new(HttpStatusCode.OK){Content=new StringContent(x,Encoding.UTF8,"application/json")};private sealed class H(Func<HttpRequestMessage,HttpResponseMessage> f):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct)=>Task.FromResult(f(r));}}